-- TravelVista - demo content.
--
-- Seven accounts covering every role and both verification states, ten
-- published destinations, a review queue and some comments. Import this
-- after database/schema.sql:
--
--   mysql -u root -p travelvista < database/seed.sql
--
-- Every account signs in with the password: password
--
-- Rows are inserted parent-first (users, then posts, then everything that
-- points at them), the same order the tables are created in schema.sql, so
-- the import works in phpMyAdmin as well as on the command line.
--
-- reset_requests and wishlist start empty on purpose: a password reset is
-- something a visitor files from the Forgot password page, and a wishlist is
-- something a signed-in user builds. Neither is seeded content.

USE travelvista;

-- Emptied child-first so the foreign keys stay satisfied at every step.
DELETE FROM `wishlist`;
DELETE FROM `reset_requests`;
DELETE FROM `post_requests`;
DELETE FROM `cost_estimates`;
DELETE FROM `comments`;
DELETE FROM `posts`;
DELETE FROM `users`;

